package br.com.lealinfo.vidraceiro;
import org.json.*;import java.io.*;import java.nio.file.Files;import java.util.*;import android.graphics.*;
/** Real HTTPS on isolated GitHub-OIDC tenant. Fault injection only for offline transport. */
final class SyncFlow {
 static void run(MeasureFlowInstrumentation t,String phase)throws Exception{
  MainActivity a=t.a;
  if(phase.startsWith("syncUnlink")){UnlinkFlow.run(t,phase);return;}
  if(phase.equals("syncPairing")){PairingFlow.run(t);return;}

  if(phase.equals("syncIdentity")){JSONObject identity=SecureGateway.identity();Files.write(new File(a.getFilesDir(),"sync-identity.json").toPath(),identity.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));return;}
  if(phase.equals("syncReopen")){waitSync(t);JSONObject p=find(a,"projects","PROJETO APP SYNC BOX");t.check(p!=null&&a.sync.deliveryStatus(p).startsWith("RECEBIDO"),"RECEBIDO persists after actual Android process restart");t.ui(()->a.editProject(p));t.check(t.find(a.root,"ENVIAR PARA O PDV")!=null&&t.find(a.root,"EXPORTAR DADOS PARA PDV")==null,"direct send control present without manual JSON step");t.ui(()->a.integration());t.check(t.find(a.root,"EXPORTAR PROJETO EM JSON")==null&&t.find(a.root,"DESVINCULAR PDV")!=null,"integration retains unlink and has no JSON export step");return;}
  JSONObject status=SyncTransport.request("/sync/status",new JSONObject());final JSONObject[] contact={null},project={null};
  if(phase.equals("syncLive")){
 JSONObject seed=new JSONObject(new String(Files.readAllBytes(new File(a.getFilesDir(),"sync-seed.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));t.check(seed.getString("code").matches("[0-9]{6}"),"real Windows generated exactly six digits");t.ui(()->a.integration());t.set("Código de conexão mostrado no PDV",seed.getString("code"));long pairingStarted=System.currentTimeMillis();t.click("CONECTAR AO PDV");waitSync(t);t.check(true,"TIMING native_pairing_ms="+(System.currentTimeMillis()-pairingStarted));t.check(!a.sync.state.optString("tenant").isEmpty(),"existing Windows code linked before data sync");
t.check(status.getString("tenant").startsWith("test-"),"real authorized isolated test tenant");t.ui(()->{a.sync.state.put("tenant",status.getString("tenant")).put("name","TESTE AUTOMATIZADO");a.sync.save();a.sync.tick();});waitSync(t);
  JSONObject bob=find(a,"clients","BOB");t.check(bob!=null&&!bob.isNull("pdvId"),"BOB from real PDV SQLite found in Android store");t.ui(()->a.contacts("clients",false));t.set("Localizar por nome ou documento","BOB");t.click("BUSCAR / ATUALIZAR CLIENTES DO PDV");waitSync(t);t.check(t.find(a.root,"BOB\n24999990000\nID PDV: "+bob.optString("pdvId")+" • "+bob.optString("document"))!=null,"BOB visible through native contact search");
  t.ui(()->{a.home();contact[0]=a.store.add("clients").put("name","CLIENTE TESTE APP").put("document","QA-APP").put("phone","24988880000").put("email","").put("address","Endereço de teste");a.store.save();});
  t.ui(()->a.projects("project"));t.click("+ NOVO PROJETO");t.set("Nome do projeto","PROJETO OFFLINE QA");t.ui(()->{a.type.setText("Box de banheiro",false);a.rows.get(0).value.setText("1200");a.rows.get(1).value.setText("1000");a.flush();a.validateProject(a.current);});
  assertDraft(t,a.current,"new valid dimensions before calculating");t.click("CALCULAR ORÇAMENTO");t.set("Valor por m² — R$ (ex.: 100,50)","100,50");t.click("CALCULAR / SALVAR ORÇAMENTO");t.dismiss();assertDraft(t,a.current,"calculate saves locally without upload");t.set("Valor por m² — R$ (ex.: 100,50)","200,00");t.click("CALCULAR / SALVAR ORÇAMENTO");t.dismiss();assertDraft(t,a.current,"recalculate remains local across automatic sync ticks");
  // Offline failure preserves durable operation UUID and local draft; no fake server response.
  t.ui(()->{a.sync.transport=new SyncTransport.Exchange(){public JSONObject call(String p,JSONObject b)throws Exception{throw new IOException("TESTE OFFLINE CONTROLADO");}public byte[] download(String u)throws Exception{throw new IOException();}public void upload(String u,byte[] b)throws Exception{throw new IOException();}};});t.click("ENVIAR PARA O PDV");waitSync(t);t.check(a.sync.link("projects",a.current.getString("id")).has("pending")&&a.sync.deliveryStatus(a.current).startsWith("PENDENTE"),"offline project queued durably through actual ENVIAR PARA O PDV button");
  final String[] operation={null};t.ui(()->{String id=a.current.getString("id");JSONObject pending=a.sync.link("projects",id).getJSONObject("pending");operation[0]=pending.getString("operationId");JSONArray out=a.sync.prepare();boolean same=false;for(int i=0;i<out.length();i++)if(id.equals(out.getJSONObject(i).optString("id")))same=operation[0].equals(out.getJSONObject(i).getString("operationId"));t.check(same,"offline project retry preserves operation UUID");});waitSync(t);
  return;
  }
  t.check(phase.equals("syncResume"),"resume phase after genuine process stop");waitSync(t);contact[0]=find(a,"clients","CLIENTE TESTE APP");t.check(contact[0]!=null,"offline customer restored in new Android process");t.ui(()->{a.sync.transport=SyncTransport.HTTPS;a.sync.tick();});waitSync(t);
  t.check(!contact[0].optString("id").isEmpty(),"app contact uploaded");
  t.ui(()->{contact[0].put("phone","24977770000");a.store.save();a.sync.tick();});waitSync(t);
  t.ui(()->{a.projects("project");});t.click("+ NOVO PROJETO");t.set("Nome do projeto","PROJETO APP SYNC BOX");t.ui(()->{a.type.setText("Box de banheiro",false);for(MainActivity.MeasureRow row:a.rows){row.value.setText("");row.unit.setSelection(2);} });t.ui(()->{a.rows.get(0).value.setText("2");a.rows.get(1).value.setText("2");a.flush();project[0]=a.current;a.validateProject(project[0]);project[0].put("budget",new JSONObject().put("quantity","2").put("price","100,50").put("service","10,00").put("discount","5,00").put("extra","2,00"));JSONArray materialIds=new JSONArray();for(int mi=0;mi<a.store.list("materials").length();mi++){JSONObject material=a.store.list("materials").getJSONObject(mi);if("VIDRO QA".equals(material.optString("name")))materialIds.put(material.getString("id"));}t.check(materialIds.length()==1,"official Windows material available in Android");project[0].put("materialLocalIds",materialIds);
   try(InputStream photo=t.getContext().getAssets().open("bathroom-cc-by-sa.jpg")){PhotoAttachment.save(a,project[0],SyncTransport.read(photo,8000000));}a.store.save();a.contacts("clients",true);});JSONObject existing=find(a,"clients","BOB");t.set("Localizar por nome ou documento","BOB");t.click("BOB\n24999990000\nID PDV: "+existing.optString("pdvId")+" • "+existing.optString("document"));t.check(selectClient(t),"select actual existing PDV client for project");t.waitForIdleSync();t.check(a.current.optString("clientLocalId").equals(existing.getString("id")),"existing client UUID selected without duplicate");t.click("CALCULAR ORÇAMENTO");t.click("CALCULAR / SALVAR ORÇAMENTO");t.dismiss();assertDraft(t,project[0],"photo, selected PDV client, values and calculation remain local until explicit send");long uploadStarted=System.currentTimeMillis();t.click("ENVIAR PARA O PDV");waitSync(t);long uploadDeadline=System.currentTimeMillis()+90000;while(System.currentTimeMillis()<uploadDeadline&&!a.sync.deliveryStatus(project[0]).startsWith("ENVIADO")){Thread.sleep(250);t.waitForIdleSync();}t.check(true,"TIMING native_project_photo_uploaded_ms="+(System.currentTimeMillis()-uploadStarted));t.check(a.sync.deliveryStatus(project[0]).startsWith("ENVIADO"),"ENVIADO while real Windows receiver is stopped; upload is not RECEBIDO");
  t.check(a.measure(project[0],"Largura").toPlainString().equals("2000"),"2 m remains 2000 mm through integration");t.ui(()->a.sync.tick());waitSync(t);t.ui(()->{t.check(a.sync.prepare().length()==0,"real ACK empties durable outbox without duplicates");});
  t.ui(()->{a.home();a.store.add("clients").put("name","QA PDV PODE VOLTAR");a.store.save();a.sync.tick();});waitSync(t);
  long deliveryStarted=System.currentTimeMillis();long untilReceived=deliveryStarted+240000;while(System.currentTimeMillis()<untilReceived&&!a.sync.deliveryStatus(project[0]).startsWith("RECEBIDO")){Thread.sleep(1000);t.waitForIdleSync();}t.check(true,"TIMING automatic_receipt_ms="+(System.currentTimeMillis()-deliveryStarted));t.check(a.sync.deliveryStatus(project[0]).startsWith("RECEBIDO"),"actual Windows import and verified JPEG acknowledged back to native Android as RECEBIDO");t.ui(()->{a.sync.link("projects",project[0].getString("id")).remove("receivedByPdv");a.sync.tick();});long refreshDeadline=System.currentTimeMillis()+90000;while(System.currentTimeMillis()<refreshDeadline&&!a.sync.deliveryStatus(project[0]).startsWith("RECEBIDO")){Thread.sleep(250);t.waitForIdleSync();}t.check(a.sync.deliveryStatus(project[0]).startsWith("RECEBIDO"),"upgrade refreshes receipt metadata without changing or duplicating existing project");
  JSONObject beforeEdit=new JSONObject(a.sync.link("projects",project[0].getString("id")).getJSONObject("baseline").toString());t.ui(()->{a.budget(project[0]);});t.set("Valor por m² — R$ (ex.: 100,50)","999,00");t.click("CALCULAR / SALVAR ORÇAMENTO");t.dismiss();Thread.sleep(6500);waitSync(t);t.ui(()->{t.check(!a.sync.link("projects",project[0].getString("id")).has("pending"),"recalculating a previously sent project does not create an automatic update");t.check(SyncCoordinator.equal(beforeEdit,a.sync.link("projects",project[0].getString("id")).getJSONObject("baseline")),"previously received PDV values are unchanged until explicit resend");project[0].put("budget",new JSONObject(beforeEdit.getJSONObject("budget").toString()));a.saveScreen=null;a.store.save();});
  Files.write(new File(a.getFilesDir(),"sync-result.json").toPath(),new JSONObject().put("client",contact[0].getString("id")).put("project",project[0].getString("id")).put("sha",project[0].getJSONObject("photoAttachment").getString("sha256")).put("tenant",status.getString("tenant")).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
 }
 static void assertDraft(MeasureFlowInstrumentation t,JSONObject project,String label)throws Exception{String id=project.getString("id");Thread.sleep(6500);waitSync(t);t.ui(()->{JSONArray changes=t.a.sync.prepare();for(int i=0;i<changes.length();i++)t.check(!id.equals(changes.getJSONObject(i).optString("id")),"draft absent from automatic outbox: "+label);JSONObject l=t.a.sync.link("projects",id);t.check(!l.has("pending")&&l.optLong("revision")==0,"no pending operation or remote revision: "+label);t.check(t.a.sync.deliveryStatus(project).startsWith("RASCUNHO"),"clear local draft status: "+label);});JSONObject page=SyncTransport.request("/sync/exchange",new JSONObject().put("changes",new JSONArray()));while(true){JSONArray records=page.getJSONArray("records");for(int i=0;i<records.length();i++)t.check(!id.equals(records.getJSONObject(i).getString("id")),"real gateway has no project before explicit send: "+label);String cursor=page.optString("cursor");if(cursor.isEmpty()||cursor.equals("null"))break;page=SyncTransport.request("/sync/exchange",new JSONObject().put("changes",new JSONArray()).put("cursor",cursor));}t.check(true,label);}
 static boolean selectClient(MeasureFlowInstrumentation t)throws Exception{long until=System.currentTimeMillis()+7000;while(System.currentTimeMillis()<until){t.waitForIdleSync();android.view.accessibility.AccessibilityNodeInfo root=t.getUiAutomation().getRootInActiveWindow();if(root!=null){for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText("SELECIONAR CLIENTE PARA O PROJETO")){if(!"SELECIONAR CLIENTE PARA O PROJETO".contentEquals(node.getText()==null?"":node.getText()))continue;android.graphics.Rect bounds=new android.graphics.Rect();node.getBoundsInScreen(bounds);if(bounds.isEmpty())continue;long time=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(time,time,android.view.MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY(),0),up=android.view.MotionEvent.obtain(time,time+80,android.view.MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY(),0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);boolean injected=t.getUiAutomation().injectInputEvent(down,true)&&t.getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();Thread.sleep(350);t.waitForIdleSync();return injected;}}Thread.sleep(150);}t.screenshot("proof-client-selection-failure");return false;}
 static JSONObject find(MainActivity a,String entity,String name)throws Exception{JSONArray list=a.store.list(entity);for(int i=0;i<list.length();i++)if(name.equals(list.getJSONObject(i).optString("name",list.getJSONObject(i).optString("title"))))return list.getJSONObject(i);return null;}
 static void waitSync(MeasureFlowInstrumentation t)throws Exception{long until=System.currentTimeMillis()+90000;while(System.currentTimeMillis()<until){Thread.sleep(250);t.waitForIdleSync();if(!t.a.sync.busy){if(!t.a.sync.state.optString("error").isEmpty()&&!t.a.sync.state.optString("error").contains("TESTE OFFLINE"))throw new Exception(t.a.sync.status());return;}}throw new Exception("sync timeout");}
}
